sens = {"l0": 0.2, "l12": 0.9, "l23": 0.7}
ranks = {k: 4 if v < 0.4 else 16 if v < 0.8 else 32 for k, v in sens.items()}
print(ranks)

grad_norm = {"l0": 0.1, "l15": 0.9, "l31": 0.7}
top = sorted(grad_norm, key=grad_norm.get, reverse=True)[:2]
print("tune:", top)

for step in [0, 1000, 5000]:
    r = 4 if step < 1000 else 16
    print(f"step {step}: rank {r}")

for step in [0, 2000, 4000]:
    r = max(4, 32 - step//250)
    print(f"step {step}: rank {r}")
